export interface FieldMetadataMeta {
  version: string
  status: string
  source: string
}

export type RequirementLevel =
  | 'required'
  | 'recommended'
  | 'optional'
  | 'definition'
  | 'none'
  | 'mixed'
  | 'conditional_required'
  | 'conditional_recommended'

export interface FieldCondition {
  field: string
  op: string
  value: string | string[]
}

export interface FieldRequirement {
  raw: string
  level: RequirementLevel
  condition: FieldCondition | null
}

export interface FieldValidation {
  /** 数值必须为整数；未指定时按有限浮点数处理。 */
  type?: 'integer' | string
  /** 含端点/不含端点的数值上下界。 */
  ge?: number
  gt?: number
  le?: number
  lt?: number
  /** 复合字段除选项外还必须提供 value。 */
  require_value?: boolean
  /** 数组条目必须具备的键。 */
  item_required?: string[]
  /** 数组条目的 value 必须为有限数。 */
  finite_value?: boolean
  /** 保留单一源未来增加的校验属性，不在生成时丢弃。 */
  [key: string]: unknown
}

export interface FieldMetadata {
  key: string
  labelZh: string
  labelEn: string
  /** 字段输入形态（原样透传自 field-source.yaml） */
  input: string
  /** 单位（xlsx 占位符 "—" 归一为 null） */
  unit: string | null
  /** 原始可选项字符串（未拆结构化词表，P3 才做） */
  options: string | null
  /** 字段校验约束（原样透传自 field-source.yaml；无约束为 null） */
  validation: FieldValidation | null
  requirement: FieldRequirement
  /** 是否属 R0 最小可复现集 */
  r0: boolean
  /** §5 过程步字段的参数组（stageGroups 的键）；其余字段为 null */
  group: string | null
  /** 表单占位符中文/英文展示；不作为提交值 */
  placeholderZh: string
  placeholderEn: string
  /** 可选的字段级帮助文本，两种语言须成对 */
  helpZh: string | null
  helpEn: string | null
  /** 条件不成立时隐藏，而非仅切换必填状态 */
  visibilityGated?: true
}

export interface StageType {
  name: string
  /** 中文显示名；name 是稳定机器码。 */
  labelZh: string
  /** 英文显示名；提交值使用 name 的稳定机器码。 */
  labelEn: string
  /** 该阶段显示哪些参数组（stageGroups 的键；common 恒显） */
  shows: string[]
  /** 该阶段额外强制必填的字段键 */
  requiredExtra?: string[]
}

